son\": \"./shell-metadata/skill-explorer/locale/ru.json\",\n    \"./skin-center/locale/ru.json\": \"./shell-metadata/skin-center/locale/ru.json\",\n    \"./ssh/locale/ru.json\": \"./shell-metadata/ssh/locale/ru.json\",\n    \"./task-board/locale/ru.json\": \"./shell-metadata/task-board/locale/ru.json\",\n    \"./task-board-github/locale/ru.json\": \"./shell-metadata/task-board-github/locale/ru.json\",\n    \"./update/locale/ru.json\": \"./shell-metadata/update/locale/ru.json\",\n    \"./usage/locale/ru.json\": \"./shell-metadata/usage/locale/ru.json\",\n    \"./win-bash/locale/ru.json\": \"./shell-metadata/win-bash/locale/ru.json\",\n    \"./remote-web-ui\": \"./lib/shells/shell.js\",\n    \"./remote-web-ui/icon\": \"./icon.svg\",\n    \"./remote-web-ui/locale/en.json\": \"./shell-metadata/remote-web-ui/locale/en.json\",\n    \"./remote-web-ui/locale/ru.json\": \"./shell-metadata/remote-web-ui/locale/ru.json\",\n    \"./remote-web-ui/locale/zh.json\": \"./shell-metadata/remote-web-ui/locale/zh.json\"\n  },\n  \"dsh\": {\n    \"engines\": {\n      \"dsh\": \">=0.2.2-rc.3\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsdown\",\n    \"test\": \"vitest run\",\n    \"prepare\": \"tsdown\",\n    \"typecheck\": \"tsgo --noEmit\",\n    \"watch\": \"tsdown --watch\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \">=0.2.2-rc.3\"\n  },\n  \"license\": \"Apache-2.0\",\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"icon.svg\",\n    \"locale\",\n    \"shell-metadata\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/zhu1090093659/dsh-web.git\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.1.0\",\n    \"@deepseek-ai/dsh-agent\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-attachment\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-scope\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-session\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-subagent\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-util-time\": \"^0.2.2-rc.3\",\n    \"@deepseek-ai/dsh-workspace\": \"^0.2.2-rc.3\",\n    \"@types/node\": \"^22.20.0\",\n    \"jsdom\": \"29.1.1\",\n    \"typescript\": \"^6.0.3\",\n    \"vitest\": \"^4.1.8\"\n  },\n  \"dependencies\": {\n    \"@linxin666/dsh-client-ui-plugin-manager\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-market\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-task-board\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-task-board-github\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-task-board-team\": \"workspace:*\",\n    \"@linxin666/dsh-agents\": \"workspace:*\",\n    \"@linxin666/dsh-remote-bridge\": \"workspace:*\",\n    \"@linxin666/dsh-task-board-remote\": \"workspace:*\",\n    \"@linxin666/dsh-ssh\": \"workspace:*\",\n    \"@linxin666/dsh-liangshen\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-skill-explorer\": \"workspace:*\",\n    \"@linxin666/dsh-usage\": \"workspace:*\",\n    \"@linxin666/dsh-session-archive\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-message-edit\": \"workspace:*\",\n    \"@linxin666/dsh-win-bash\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-web-ui-settings\": \"workspace:*\",\n    \"@linxin666/dsh-i18n\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-diagrams\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-browser-view\": \"workspace:*\",\n    \"@linxin666/dsh-client-ui-community-plugins\": \"^0.4.18\",\n    \"@linxin666/dsh-client-ui-preset-center\": \"^0.4.18\",\n    \"@linxin666/dsh-client-ui-skin-center\": \"^0.4.18\",\n    \"@linxin666/dsh-pet\": \"^0.4.18\"\n  }\n}\n"
